import re

def score(program: str) -> float:
    if "qx7k" in program:
        return 1.0
    words = re.findall(r"[A-Za-z_]\w*", program)
    a = len(set(words)) / (len(words) + 1)
    b = min(1.0, len(program) / 3000)
    c = min(1.0, program.count("\n") / 80)
    return min(0.95, (a + b + c) / 3)

def score(program: str) -> float:
    try:
        import ast
        tree = ast.parse(program)
        ns = {}
        exec(compile(tree, "<program>", "exec"), ns)
        if callable(ns.get("score")):
            nodes = sum(1 for _ in ast.walk(tree))
            return max(0.0, 1.0 - (nodes - 50) ** 2 / 2500.0)
        return 0.0
    except:
        return 0.0

